  if(t===1){const [w,a]=pick(ANT),others=shuffle([...SYN.map(p=>p[1]),...ANT.filter(p=>p[0]!==w).map(p=>p[0])]).slice(0,3);
    return {prompt:`Which word means the <b>opposite</b> of <b>"${w}"</b>?`,...strChoices(a,others),hint:`Opposites are as different as day and night.`,explain:`"${w}" and "<b>${a}</b>" are <b>antonyms</b>. They mean opposite things.`};}
