function geoX(t){
  if(t===5){const pool=shuffle(LL_CITIES.slice()).slice(0,4),c=pool[0],k=R(0,2);
    if(k===0){const la=near2(c[1]),lo=near2(-c[2]);const by=pool.slice().sort((a,b)=>a[0].localeCompare(b[0]));
      const dd=x=>Math.hypot(x[1]-la,-x[2]-lo),dc=dd(c);if(dc>1.1||pool.some(x=>x!==c&&dd(x)<dc+1.2))return geoX(t);
      return {prompt:`Which city is closest to <b>${la}°N, ${lo}°W</b>?`,visual:llMap(by,null),...strChoices(c[0],by.slice(1).map(x=>x[0]).concat(by.map(x=>x[0]))),
        hint:`Find the ${la}°N line (going across). Then find the ${lo}°W line (going up and down). Where do they cross?`,explain:`${la}°N and ${lo}°W cross right near <b>${c[0]}</b>.`}}
    if(k===1){const la=near2(c[1]);if(Math.abs(c[1]-la)>.45)return geoX(t);
      return {prompt:`About what <b>latitude</b> is <b>${c[0]}</b>?`,visual:llMap(pool,c[0]),...strChoices(`${la}°N`,[`${la+2}°N`,`${la-2}°N`,`${la+4}°N`,`${la-4}°N`].filter(x=>parseInt(x)>=32&&parseInt(x)<=42).concat([`${near2(-c[2])}°W`])),
        hint:`Latitude lines go <b>across</b>, like the rungs of a ladder. Their numbers are on the right side and end in N.`,explain:`${c[0]} sits near the <b>${la}°N</b> line. Latitude tells how far north of the equator a place is.`}}
    const lo=near2(-c[2]);if(Math.abs(-c[2]-lo)>.45)return geoX(t);
    return {prompt:`About what <b>longitude</b> is <b>${c[0]}</b>?`,visual:llMap(pool,c[0]),...strChoices(`${lo}°W`,[`${lo+2}°W`,`${lo-2}°W`,`${lo+4}°W`,`${lo-4}°W`].filter(x=>parseInt(x)>=114&&parseInt(x)<=124).concat([`${near2(c[1])}°N`,`${lo-6}°W`])),
      hint:`Longitude lines run <b>up and down</b> (north to south). Their numbers are at the bottom and end in W.`,explain:`${c[0]} sits near the <b>${lo}°W</b> line. Longitude tells how far west (or east) a place is.`}}
  const f=pick(t===6?CA_REGIONS:CA_GOV);return {prompt:f[0],...strChoices(f[1],f[2]),hint:f[3],explain:f[4],long:[f[1],...f[2]].some(c=>c.length>30)};
}
