const LISTEN_Q=LISTEN.flatMap((C,ci)=>C.q.map((_,qi)=>[ci,qi]));
function listenCard(C){return `<div class="listen" data-txt="${esc(C.txt)}"><div class="lhead">${ICON&&ICON.sound?ICON.sound:''}<b>${esc(C.t)}</b></div><p class="lnote">Listen carefully. The words are hidden, just like on the listening test!</p><div class="lbtns"><button type="button" class="go lplay">${canSpeak?'▶ Listen':'Show the words'}</button>${canSpeak?'<button type="button" class="go alt small lshow">Show the words</button>':''}</div><div class="ltext" hidden>${esc(C.txt)}</div></div>`}
function genListen(t){const [ci,qi]=LISTEN_Q[t%LISTEN_Q.length],C=LISTEN[ci],Q=C.q[qi];
  return {prompt:Q[0],visual:listenCard(C),...strChoices(Q[1],shuffle(Q[2].slice())),hint:Q[3],explain:Q[4],listen:C.txt,long:[Q[1],...Q[2]].some(c=>c.length>30),render:c=>esc(c)}}
function listenRound(isl){const cs=dealTypes('listen_c',LISTEN.length,2);return cs.flatMap(ci=>{const off=LISTEN_Q.findIndex(x=>x[0]===ci);return LISTEN[ci].q.map((_,qi)=>makeQ(isl,off+qi,R(1,2e9)))})}
function wireListen(){const L=document.querySelector('#visual .listen');if(!L)return;const txt=L.dataset.txt,play=L.querySelector('.lplay'),show=L.querySelector('.lshow'),box=L.querySelector('.ltext');
  const reveal=()=>{box.hidden=false;if(show)show.hidden=true};
  play.onclick=()=>{if(!canSpeak){reveal();play.hidden=true;return}stopSpeak();speak(txt,{user:true});play.textContent='↻ Listen again';S.heard=1};
  if(show)show.onclick=()=>{reveal();bump&&bump('w')}}
/* ===== closing the last gaps in the 4th grade standards ===== */
/* 4.OA.2: "times as many" vs "more than" */
function genCmpEq(){const [a,b]=shuffle([...NAMES]).slice(0,2),n=R(3,9),k=R(2,9),times=coin(),th=pick(['stickers','shells','marbles','books']);
  const ans=times?`${a}: ${n} × ${k} = ${n*k}`:`${a}: ${k} + ${n} = ${n+k}`;
  return {prompt:`${b} has <b>${k}</b> ${th}. ${a} has <b>${times?`${n} times as many`:`${n} more`}</b> ${th} ${times?'as':'than'} ${b}. Which shows how to find how many ${a} has?`,
    ...strChoices(ans,[times?`${a}: ${k} + ${n} = ${n+k}`:`${a}: ${n} × ${k} = ${n*k}`,`${a}: ${Math.max(k,n)} − ${Math.min(k,n)} = ${Math.abs(k-n)}`,times?`${a}: ${n*k} ÷ ${k} = ${n}`:`${a}: ${k} × 2 = ${k*2}`]),long:true,
    hint:`"Times as many" means multiply. "More than" means add.`,explain:times?`<b>${n} times as many</b> as ${k} means ${n} groups of ${k}: ${n} × ${k} = <b>${n*k}</b>.`:`<b>${n} more</b> than ${k} means add: ${k} + ${n} = <b>${n+k}</b>.`}}
/* 4.OA.5: features of a pattern that the rule does not say */
function genPatFeat(){const s=R(1,9),k=pick([2,4,6,10,3,5]),seq=[0,1,2,3,4,5].map(i=>s+i*k);let ans,w;
  if(k%2===0){ans=s%2?'All the numbers are odd.':'All the numbers are even.';w=[s%2?'All the numbers are even.':'All the numbers are odd.','The numbers go odd, even, odd, even.','Every number ends in 0.']}
  else{ans=s%2?'The numbers go odd, even, odd, even.':'The numbers go even, odd, even, odd.';w=['All the numbers are odd.','All the numbers are even.','Every number is a multiple of 10.']}
  return {prompt:`The rule is <b>"start at ${s}, add ${k}"</b>. Which is true about the pattern?`,visual:`<div class="seq">${seq.map(x=>`<span>${x}</span>`).join('')}</div>`,...strChoices(ans,w),long:true,
    hint:`Look at each number. Is it odd or even? Adding an even number keeps odd/even the same. Adding an odd number switches it.`,explain:`${seq.join(', ')}: ${ans} Adding ${k} (${k%2?'odd':'even'}) ${k%2?'switches between odd and even':'keeps odd or even the same'}.`}}
/* 4.MD.2: measurement on a number line */
function genMeasLine(){const unit=pick([['minutes',0,60,5,'Pip\'s walk','walked'],['centimeters',0,100,10,'The ribbon','is'],['milliliters',0,500,50,'The water','was poured']]);
  const [u,lo,hi,step,who]=unit,n=(hi-lo)/step;let a,b;do{a=R(0,n-2)*step;b=R(1,n)*step}while(b-a<step*2);
  const X=v=>20+(v-lo)/(hi-lo)*300;let tk='';for(let v=lo;v<=hi;v+=step)tk+=`<line x1="${X(v)}" y1="60" x2="${X(v)}" y2="${(v-lo)%(step*2)===0?72:68}" stroke="#1f3557" stroke-width="2"/>${(v-lo)%(step*2)===0?`<text x="${X(v)}" y="88" text-anchor="middle" ${FONT} font-size="12" fill="#1f3557">${v}</text>`:''}`;
  const vis=`<svg viewBox="0 0 340 100" style="width:380px;max-width:100%" role="img" aria-label="Number line"><line x1="20" y1="60" x2="320" y2="60" stroke="#1f3557" stroke-width="3"/>${tk}<rect x="${X(a)}" y="44" width="${X(b)-X(a)}" height="10" rx="5" fill="#ff9f43"/><circle cx="${X(a)}" cy="49" r="7" fill="#2f9fe0" stroke="#1f3557" stroke-width="2"/><circle cx="${X(b)}" cy="49" r="7" fill="#e2558f" stroke="#1f3557" stroke-width="2"/><text x="${X(a)}" y="34" text-anchor="middle" ${FONT} font-size="12" fill="#2f9fe0">start</text><text x="${X(b)}" y="34" text-anchor="middle" ${FONT} font-size="12" fill="#e2558f">end</text><text x="170" y="98" text-anchor="middle" font-size="11" fill="#506686" font-weight="700">${u}</text></svg>`;
  return {prompt:`The number line shows the start and end. How many <b>${u}</b> is it from start to end?`,visual:vis,unit:u==='milliliters'?'mL':u==='centimeters'?'cm':'min',...numChoices(b-a,[b,a,b-a+step,b-a-step].filter(x=>x>0)),
    hint:`Read the start and the end. Then subtract: end − start. Each small tick is ${step}.`,explain:`Start: ${a}. End: ${b}. ${b} − ${a} = <b>${b-a} ${u}</b>.`}}
/* RI.4.5 text structure */
const TSTRUCT=[['First, the caterpillar hatches from a tiny egg. Next, it eats and grows for about two weeks. Then it forms a chrysalis. Finally, a butterfly comes out.','Sequence (time order)'],
 ['Frogs and toads are both amphibians. Frogs have smooth, wet skin, but toads have dry, bumpy skin. Frogs have long legs for jumping, while toads have short legs for walking.','Compare and contrast'],
 ['Heavy rain fell for three days. Because of this, the river rose over its banks. As a result, many roads near the river were closed.','Cause and effect'],
 ['Many birds crashed into the big glass windows at our school. To solve this, students stuck colorful paper shapes on the glass. Now the birds can see the windows and fly around them.','Problem and solution'],
 ['A volcano is an opening in Earth\'s crust. Hot melted rock called magma rises up through it. Volcanoes can be found on land and under the ocean.','Description'],
 ['The town library was too small for all its books. So the people raised money with bake sales and a fun run. In two years, they built a bigger library.','Problem and solution'],
 ['When water gets very cold, it freezes into ice. Because ice takes up more space than water, frozen pipes can crack.','Cause and effect'],
 ['Dolphins and sharks both live in the ocean. Dolphins are mammals that breathe air, but sharks are fish that breathe with gills.','Compare and contrast'],
 ['In 1769, the first mission was built in San Diego. Over the next 54 years, 20 more missions were built. The last one was finished in Sonoma in 1823.','Sequence (time order)']];
function genStruct(t){const [p,a]=TSTRUCT[t%TSTRUCT.length];return {prompt:`<div class="passage"><p>${p}</p></div>How is this paragraph <b>organized</b>?`,...strChoices(a,shuffle(['Sequence (time order)','Compare and contrast','Cause and effect','Problem and solution','Description'].filter(x=>x!==a))),
  hint:`Look for clue words: first/next/then (sequence), but/while/both (compare), because/as a result (cause and effect), to solve (problem and solution).`,
  explain:`Clue words show it: <b>${a}</b>.`,long:true}}
/* L.4.4c dictionary, L.4.3 formal English and punctuation for effect, W.4.3 dialogue */
const DICT=[['bank','1. land along the side of a river 2. a place where people keep money 3. to tilt an airplane while turning',['We had a picnic on the <b>bank</b> of the river.',1],['Mom put her paycheck in the <b>bank</b>.',2]],
 ['bat','1. a flying mammal that is active at night 2. a wooden stick used to hit a ball 3. to blink (your eyes)',['The <b>bat</b> flew out of the cave at dusk.',1],['Leo swung the <b>bat</b> and hit a home run.',2]],
 ['fair','1. treating everyone equally 2. an outdoor event with rides and games 3. light in color',['It is not <b>fair</b> that only one team gets the ball.',1],['We rode the Ferris wheel at the county <b>fair</b>.',2]],
 ['bark','1. the sound a dog makes 2. the outer covering of a tree trunk',['The <b>bark</b> of the oak tree was rough.',2],['I heard a loud <b>bark</b> from next door.',1]],
 ['light','1. not heavy 2. brightness that lets us see 3. to start a fire',['This backpack is so <b>light</b>!',1],['Turn on the <b>light</b>, please.',2]],
 ['present','1. a gift 2. here, not absent 3. to show or give to a group',['Everyone in class was <b>present</b> today.',2],['Maya will <b>present</b> her project on Friday.',3]]];
const GUIDE=[['apple','berry',['banana','bike','avocado','cherry'],'banana'],['magic','mitten',['milk','map','moon','music'],'milk'],['seal','snow',['shell','sail','sun','sock'],'shell'],['table','tiger',['tent','train','turtle','taco'],'tent'],['rabbit','robin',['river','rocket','rain','rose'],'river']];
function genDict(t){if(t===6){const [w,def,s1,s2]=pick(DICT),[s,n]=coin()?s1:s2,defs=def.split(/\s(?=\d\.)/);
    return {prompt:`<div class="dict"><b>${w}</b> <i>(noun or verb)</i><br>${defs.join('<br>')}</div>Which meaning of <b>${w}</b> is used in this sentence?<br><i>"${s}"</i>`,...strChoices(`Meaning ${n}`,['Meaning 1','Meaning 2','Meaning 3'].filter((x,i)=>i<defs.length&&x!==`Meaning ${n}`)),
      hint:`Try each meaning in the sentence. Which one makes sense?`,explain:`In this sentence, <b>${w}</b> means "${defs[n-1].replace(/^\d\.\s*/,'')}" (meaning ${n}).`}}
  const [a,b,opts,ans]=pick(GUIDE);return {prompt:`A dictionary page has the guide words <b>${a}</b> and <b>${b}</b>. Which word would you find on this page?`,...strChoices(ans,opts.filter(x=>x!==ans)),
    hint:`Guide words show the first and last word on the page. Your word must come between them in ABC order.`,explain:`<b>${ans}</b> comes after "${a}" and before "${b}" in ABC order.`}}
const FORMAL=[['You are writing a letter to the principal. Which sentence is the most <b>formal</b>?','I would like to ask if our class can plant a garden.',['Hey! Can we do a garden?? Pleeease!','Garden. Yes or no?','Yo, we want a garden, okay?']],
 ['You are giving a report to the class about whales. Which sentence fits <b>best</b>?','Blue whales are the largest animals that have ever lived.',['Blue whales are super duper huge, LOL.','Whales? So big. Like, wow.','OMG blue whales are big.']],
 ['Which sentence would you use when texting a <b>friend</b> (informal)?','Wanna come over after school?',['I would like to invite you to visit my home after school.','Dear Sir, please attend my residence.','To whom it may concern: come over.']]];
const PUNCT=[['Which ending shows that the speaker is <b>excited</b>?','"We won the championship!"',['"We won the championship."','"We won the championship?"','"We won the championship,"']],
 ['Which sentence uses punctuation to show a <b>question</b>?','"Where did my backpack go?"',['"Where did my backpack go."','"Where did my backpack go!"','"Where, did my backpack go"']],
 ['Which sentence shows a <b>surprise</b> best?','"Look out! A snake!"',['"Look out. A snake."','"Look out, a snake."','"look out a snake"']]];
const DIALOGUE=[['Which sentence shows a character\'s feeling through <b>dialogue</b>?','"I can\'t believe I finally did it!" Ana shouted, jumping up and down.',['Ana was happy.','Ana felt good about it.','Ana did it.']],
 ['Which sentence <b>shows</b> (not tells) that Ben is nervous?','Ben\'s hands shook as he whispered, "Is it my turn already?"',['Ben was nervous.','Ben felt nervous about his turn.','Ben was very, very nervous.']],
 ['Which line of dialogue is punctuated <b>correctly</b>?','"Let\'s go to the park," said Mom.',['"Let\'s go to the park" said Mom.','"Let\'s go to the park, said Mom."','Let\'s go to the park, "said Mom".']]];
function genLang(t){const [p,a,w]=pick(t===13?FORMAL:t===14?PUNCT:DIALOGUE);return {prompt:p,...strChoices(a,w),long:true,render:c=>esc(c),
  hint:t===13?'Formal language is polite and uses complete sentences. Informal is how you talk to friends.':t===14?'An exclamation point shows strong feeling. A question mark asks something.':'Dialogue is what a character says, inside quotation marks. Showing uses actions and words instead of just naming the feeling.',
  explain:`<b>${esc(a)}</b>`}}
/* science: coded messages (4-PS4-3), weathering and erosion (4-ESS2-1), hazards and engineering (4-ESS3-2, ETS), collisions (4-PS3-3) */
const CODE={A:'•—',B:'—•••',E:'•',H:'••••',I:'••',L:'•—••',O:'———',P:'•——•',S:'•••',T:'—',N:'—•'};
const SCI_ERO=[['A canyon with tall walls slowly got deeper over millions of years. A river runs along the bottom. What most likely made the canyon?','Water flowing and carrying away rock',['A single earthquake','People digging','Wind from one storm']],
 ['Rocks in the desert have been carved into strange round shapes. There is very little water. What most likely shaped them?','Wind blowing sand against the rocks',['Ocean waves','Ice in glaciers','Plant roots']],
 ['A tree root grew into a crack in a big rock. Years later, the rock split apart. What is this an example of?','Weathering by plants',['Erosion by wind','A volcano','Melting']],
 ['Water seeps into a crack in a rock, freezes, and expands. After many winters, the rock breaks. What caused this?','Ice (freezing and thawing)',['Sunlight','Animals','Wind']],
 ['Which would slow down erosion on a hillside the most?','Planting grass and trees on the hill',['Removing all the plants','Pouring water down the hill','Digging trenches']]];
const SCI_HAZ=[['A town is near a river that floods every spring. Which solution would best protect the houses?','Build the houses on raised platforms (stilts)',['Build the houses with bigger windows','Plant flowers in front of the houses','Build the houses closer to the river']],
 ['Engineers want buildings to survive earthquakes. Which design is best?','A building with a flexible frame that can sway without breaking',['A tall building made of loose bricks','A building with no foundation','A heavy roof on thin walls']],
 ['Scientists put sensors along a coast to warn people about tsunamis. What is the main purpose?','To give people time to get to higher ground',['To stop the waves completely','To make the waves bigger','To measure how warm the water is']],
 ['A class tests three roof designs to keep a model house dry. Design A leaks a lot, B leaks a little, C does not leak but costs the most. Their budget is small. Which is the best <b>next step</b>?','Improve design B so it stops leaking but still costs little',['Pick A because it is cheapest','Give up','Pick C without thinking about cost']],
 ['To protect a hillside town from mudslides, which is the best idea?','Build retaining walls and plant deep-rooted plants',['Cut down all the trees','Build more houses on the slope','Pave the hillside with sidewalks']]];
function sciNew(k){
  if(k===7){const words=['HI','SO','TO','NO','HOT','PET','TAB','BOAT','PIE','LEO'],w=pick(words),enc=[...w].map(c=>CODE[c]).join('  /  ');
    const opts=shuffle(words.filter(x=>x!==w)).sort((x,y)=>Math.abs(x.length-w.length)-Math.abs(y.length-w.length)).slice(0,3);const all=[w,...opts].join('');const key=Object.entries(CODE).filter(([c])=>all.includes(c)).map(([c,v])=>`<span><b>${c}</b> ${v}</span>`).join('');
    return {prompt:`Pip sends a message with flashes of light: short (•) and long (—). Use the code key. What does the message say?<div class="ckey">${key}</div><div class="cmsg">${enc}</div>`,...strChoices(w,opts),
      hint:`Decode one letter at a time. Letters are separated by /.`,explain:`${[...w].map(c=>`${CODE[c]} = ${c}`).join(', ')}. The message is <b>${w}</b>. Patterns of light or sound can carry information, like Morse code.`}}
  if(k===8||k===9){const [p,a,w]=pick(k===8?SCI_ERO:SCI_HAZ);return {prompt:p,...strChoices(a,w),long:true,render:c=>c,hint:k===8?'Weathering breaks rock. Erosion moves the pieces. Think about water, wind, ice and plants.':'Pick the solution that solves the problem and fits the limits (cost, safety).',explain:`<b>${a}</b>`}}
  const fast=coin(),vis=`<svg viewBox="0 0 320 120" style="width:340px;max-width:100%" role="img" aria-label="Two collisions"><text x="80" y="18" text-anchor="middle" ${FONT} font-size="14">Cart A</text><text x="240" y="18" text-anchor="middle" ${FONT} font-size="14">Cart B</text>
    <rect x="20" y="60" width="44" height="26" rx="6" fill="#2f9fe0" stroke="#1f3557" stroke-width="2"/><path d="M${fast?'68 73 h40':'68 73 h14'}" stroke="#e2558f" stroke-width="4" marker-end="url(#ca)"/><rect x="120" y="60" width="24" height="26" rx="4" fill="#ffc23d" stroke="#1f3557" stroke-width="2"/>
    <rect x="180" y="60" width="44" height="26" rx="6" fill="#2f9fe0" stroke="#1f3557" stroke-width="2"/><path d="M${fast?'228 73 h14':'228 73 h40'}" stroke="#e2558f" stroke-width="4" marker-end="url(#ca)"/><rect x="280" y="60" width="24" height="26" rx="4" fill="#ffc23d" stroke="#1f3557" stroke-width="2"/>
    <text x="80" y="110" text-anchor="middle" font-size="12" fill="#506686">${fast?'fast':'slow'}</text><text x="240" y="110" text-anchor="middle" font-size="12" fill="#506686">${fast?'slow':'fast'}</text><defs><marker id="ca" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5L0 10z" fill="#e2558f"/></marker></defs></svg>`;
  const win=fast?'Cart A':'Cart B';
  return {prompt:`Two identical carts roll into identical blocks. The arrows show their speed. Which cart will push its block <b>farther</b>?`,visual:vis,choices:['Cart A','Cart B','Both the same'],answer:win,
    hint:`A faster object has more energy. In a collision, energy moves to the other object.`,explain:`<b>${win}</b> is faster, so it has more energy to pass to the block in the collision.`}}
