/* RF.4.4 fluency check for grown-ups: the child reads a passage aloud, a grown-up times it */
const FLU_BENCH='About 94 words per minute in fall, 120 in winter, 133 in spring is typical (50th percentile) for 4th grade, from Hasbrouck & Tindal (2017).';
function openFluency(){const C=pick(LISTEN),words=C.txt.split(/\s+/).length;let t0=0,tid=0;
  overlay(`<div class="eyebrow">Reading fluency check</div><h3 style="margin:0">${esc(C.t)}</h3><p class="note">For a grown-up: press Start when your child begins reading <b>out loud</b>, and Stop when they finish. Then enter how many words they misread or skipped.</p><div class="flutext">${esc(C.txt)}</div>
    <div class="actrow"><button type="button" class="go" id="fluGo">Start</button><span class="flut" id="fluT">0.0 s</span></div><div id="fluRes"></div><div class="actrow"><button type="button" class="go alt" id="fluClose">Close</button></div>`,()=>{
    $('#ocard').classList.add('wide');const close=()=>{clearInterval(tid);$('#ocard').classList.remove('wide');closeOverlay();if(curScreen==='parent')renderParent()};$('#fluClose').onclick=close;
    $('#fluGo').onclick=()=>{if(!t0){t0=Date.now();$('#fluGo').textContent='Stop';tid=setInterval(()=>{$('#fluT').textContent=((Date.now()-t0)/1000).toFixed(1)+' s'},100);return}
      clearInterval(tid);const sec=(Date.now()-t0)/1000;$('#fluGo').remove();
      $('#fluRes').innerHTML=`<p>Time: <b>${sec.toFixed(1)} s</b>. Words in the passage: <b>${words}</b>.</p><label class="flul">Words misread or skipped: <input type="number" id="fluErr" min="0" max="${words}" value="0"></label><div class="actrow"><button type="button" class="go" id="fluSave">Save</button></div>`;
      $('#fluSave').onclick=()=>{if(sec<10){$('#fluRes').innerHTML='<p class="pzno">That was very quick. Please time a whole read-aloud from start to finish.</p>';return}const e=Math.max(0,Math.min(words,+$('#fluErr').value||0)),wcpm=Math.round((words-e)/(sec/60)),acc=Math.round((words-e)/words*100);
        G.flu=G.flu||[];G.flu.unshift({ts:Date.now(),t:C.t,wcpm,acc});if(G.flu.length>30)G.flu.length=30;save();
        $('#fluRes').innerHTML=`<p class="pzok"><b>${wcpm}</b> words correct per minute · <b>${acc}%</b> accuracy</p><p class="note">${FLU_BENCH}</p>`}}})}
function fluencyParentHTML(){const L=G.flu||[];return `<div class="pcard wide"><h4>Reading fluency</h4><p class="note">Reading out loud smoothly and accurately (RF.4.4). Takes 1 minute: your child reads a short passage aloud while you time it. ${FLU_BENCH}</p>${L.length?`<ul class="mist">${L.slice(0,6).map(x=>`<li>${x.wcpm} words/min · ${x.acc}% accurate<small>${new Date(x.ts).toLocaleDateString(undefined,{month:'short',day:'numeric'})} · ${esc(x.t)}</small></li>`).join('')}</ul>`:'<p>No checks yet.</p>'}<button type="button" class="go small" id="pFlu">Start a fluency check</button></div>`}
/* RL.4.9: two folktales from different cultures with the same theme */
function passageHTML(P){if(P.p2)return `<div class="passage two"><h4>${P.t}</h4><div class="ptwo"><div><h5>${P.t1}</h5><p>${P.p.join(' ')}</p></div><div><h5>${P.p2.t}</h5><p>${P.p2.p.join(' ')}</p></div></div></div>`;
  return `<div class="passage${P.lines?' lines':''}"><h4>${P.t}</h4>${P.lines?`<div class="plines">${P.p.map(l=>l?`<span class="ln">${l}</span>`:'<span class="ln gap"></span>').join('')}</div>`:`<p>${P.p.join(' ')}</p>`}${P.fig||''}</div>`}
